package io.floci.aws.services.account;

import com.fasterxml.jackson.databind.JsonNode;
import io.floci.aws.core.common.AwsException;
import io.floci.aws.core.common.RequestConstraintCheck;

import java.util.List;

/**
 * Checks the primary contact requests against the constraints generated by
 * {@code tools/aws/regen_account_shapes.py}. A member of the wrong JSON type answers
 * {@code SerializationException}, as a non-string {@code AccountId} does on the alternate contact
 * operations; every other violation is a {@code ValidationException} in the standard wording.
 */
final class AccountRequestShapes {

    private static final RequestConstraintCheck.Messages VALIDATION =
            RequestConstraintCheck.standardMessages("ValidationException");

    private static final RequestConstraintCheck CHECK = RequestConstraintCheck.load(
            "aws/account-request-shapes.json", "Account Management request shapes",
            new RequestConstraintCheck.Messages() {
                @Override
                public AwsException type(String path, String type) {
                    String member = path.substring(path.indexOf('.') + 1);
                    return new AwsException("SerializationException", member + " must be a " + type + ".", 400);
                }

                @Override
                public AwsException bounds(String path, String type, Long min, Long max, Number size) {
                    return VALIDATION.bounds(path, type, min, max, size);
                }

                @Override
                public AwsException pattern(String path, String pattern) {
                    return VALIDATION.pattern(path, pattern);
                }

                @Override
                public AwsException enumValue(String path, List<String> values) {
                    return VALIDATION.enumValue(path, values);
                }

                @Override
                public AwsException required(String path) {
                    return VALIDATION.required(path);
                }
            });

    private AccountRequestShapes() {
    }

    static void check(String operation, JsonNode request) {
        CHECK.check(operation, request);
    }
}
